mapper.select:
select exists(
    select 1
    from pg_catalog.pg_ts_config
    where cfgname = #{configName}
)

select exists(
    select 1
    from pg_catalog.pg_ts_config c
    join pg_catalog.pg_namespace n on n.oid = c.cfgnamespace
    where c.cfgname = #{configName}
      and n.nspname = #{schemaName}
)
